package ru.folio.notes;

import java.util.*;

/** Conservative, bounded geometric fitting. Invoked by an explicit end-of-stroke hold. */
public final class ShapeRecognizer {
    static final int SAMPLES=96;
    public static boolean eligible(String tool){return Arrays.asList("pen","fountain","pencil","brush","marker","rainbow").contains(tool);}
    static Ink.Pt pt(float x,float y){return new Ink.Pt(x,y,1,0,0);}
    static float length(List<Ink.Pt> points){float sum=0;for(int i=1;i<points.size();i++)sum+=Ink.dist(points.get(i-1).x,points.get(i-1).y,points.get(i).x,points.get(i).y);return sum;}
    static float area(List<Ink.Pt> points){if(points.isEmpty())return 0;double a=0;float ox=points.get(0).x,oy=points.get(0).y;for(int i=0;i<points.size();i++){Ink.Pt p=points.get(i),q=points.get((i+1)%points.size());a+=(double)(p.x-ox)*(q.y-oy)-(double)(q.x-ox)*(p.y-oy);}return (float)(a/2);}
    static ArrayList<Ink.Pt> bounded(List<Ink.Pt> points){ArrayList<Ink.Pt> out=new ArrayList<>();int step=Math.max(1,(points.size()+2047)/2048);for(int i=0;i<points.size();i+=step)out.add(points.get(i));if(!points.isEmpty()&&out.get(out.size()-1)!=points.get(points.size()-1))out.add(points.get(points.size()-1));return out;}
    static ArrayList<Ink.Pt> denoise(ArrayList<Ink.Pt> points){if(points.size()<6)return points;for(int pass=0;pass<2;pass++){ArrayList<Ink.Pt> next=new ArrayList<>();next.add(points.get(0));for(int i=1;i<points.size()-1;i++){Ink.Pt a=points.get(i-1),b=points.get(i),c=points.get(i+1);next.add(pt((a.x+2*b.x+c.x)/4,(a.y+2*b.y+c.y)/4));}next.add(points.get(points.size()-1));points=next;}return points;}
    static ArrayList<Ink.Pt> resample(List<Ink.Pt> points,int count){ArrayList<Ink.Pt> result=new ArrayList<>();if(points.isEmpty())return result;float total=length(points);if(total<.001f){for(int i=0;i<count;i++)result.add(points.get(0));return result;}int segment=1;float before=0,part=Ink.dist(points.get(0).x,points.get(0).y,points.get(1).x,points.get(1).y);for(int i=0;i<count;i++){float distance=total*i/(count-1f);while(segment<points.size()-1&&before+part<distance){before+=part;segment++;part=Ink.dist(points.get(segment-1).x,points.get(segment-1).y,points.get(segment).x,points.get(segment).y);}Ink.Pt a=points.get(segment-1),b=points.get(segment);float t=part<.00001f?0:Ink.clamp((distance-before)/part,0,1);result.add(pt(a.x+(b.x-a.x)*t,a.y+(b.y-a.y)*t));}return result;}
    static float[] bounds(List<Ink.Pt> points){float l=Float.MAX_VALUE,t=l,r=-l,b=-l;for(Ink.Pt p:points){l=Math.min(l,p.x);t=Math.min(t,p.y);r=Math.max(r,p.x);b=Math.max(b,p.y);}return new float[]{l,t,r,b};}
    static float snapAngle(float angle){float target=Math.round(angle/(Math.PI/4))*(float)(Math.PI/4);return Math.abs(InkGeometry.delta(angle,target))<Math.toRadians(6)?target:angle;}
    static Ink.Stroke stroke(Ink.Stroke source,List<Ink.Pt> points){Ink.Stroke result=new Ink.Stroke();result.color=source.color;result.width=source.width;result.action=source.action;result.text=source.text;result.revealed=source.revealed;result.cuts.addAll(source.cuts);result.tool=Arrays.asList("marker","rainbow","pencil").contains(source.tool)?source.tool:"pen";result.points.clear();if(source.tool.equals("marker")&&!source.points.isEmpty()){float angle=source.points.get(source.points.size()-1).angle;for(Ink.Pt p:points)result.points.add(new Ink.Pt(p.x,p.y,1,0,angle));}else result.points.addAll(points);return result;}
    public static final class Result {
        public final String kind;public final Ink.Stroke stroke;final ArrayList<Ink.Pt> from,to;
        Result(String kind,Ink.Stroke original,List<Ink.Pt> target,boolean closed){this.kind=kind;
            ArrayList<Ink.Pt> matched=new ArrayList<>(target);
            if(closed){if(Math.signum(area(original.points))!=Math.signum(area(matched)))Collections.reverse(matched);if(matched.size()>1&&Ink.dist(matched.get(0).x,matched.get(0).y,matched.get(matched.size()-1).x,matched.get(matched.size()-1).y)<.001f)matched.remove(matched.size()-1);int best=0;float distance=Float.MAX_VALUE,bestT=0;Ink.Pt first=original.points.get(0);for(int i=0;i<matched.size();i++){Ink.Pt a=matched.get(i),b=matched.get((i+1)%matched.size());float dx=b.x-a.x,dy=b.y-a.y,len=dx*dx+dy*dy,t=len<1e-8f?0:Ink.clamp(((first.x-a.x)*dx+(first.y-a.y)*dy)/len,0,1),d=Ink.dist(first.x,first.y,a.x+t*dx,a.y+t*dy);if(d<distance){distance=d;best=i;bestT=t;}}Ink.Pt a=matched.get(best),b=matched.get((best+1)%matched.size()),start=pt(a.x+(b.x-a.x)*bestT,a.y+(b.y-a.y)*bestT);ArrayList<Ink.Pt> reordered=new ArrayList<>();reordered.add(start);for(int i=1;i<=matched.size();i++){Ink.Pt q=matched.get((best+i)%matched.size());if(Ink.dist(q.x,q.y,reordered.get(reordered.size()-1).x,reordered.get(reordered.size()-1).y)>.0001f)reordered.add(q);}if(Ink.dist(start.x,start.y,reordered.get(reordered.size()-1).x,reordered.get(reordered.size()-1).y)>.0001f)reordered.add(start);matched=reordered;}
            stroke=ShapeRecognizer.stroke(original,matched);from=resample(bounded(original.points),SAMPLES);to=resample(matched,SAMPLES);
        }
        public Ink.Stroke frame(float t){if(t>=1)return stroke;float k=t*t*(3-2*t);ArrayList<Ink.Pt> p=new ArrayList<>();for(int i=0;i<SAMPLES;i++)p.add(pt(from.get(i).x+(to.get(i).x-from.get(i).x)*k,from.get(i).y+(to.get(i).y-from.get(i).y)*k));return ShapeRecognizer.stroke(stroke,p);}
    }
    public static Result recognize(Ink.Stroke source,float unit){if(source==null||!eligible(source.tool)||source.points.size()<2)return null;Ink.Stroke local=new Ink.Stroke();local.tool=source.tool;local.width=source.width;local.color=source.color;local.action=source.action;float ox=source.points.get(0).x,oy=source.points.get(0).y;for(Ink.Pt p:bounded(source.points)){if(!Float.isFinite(p.x)||!Float.isFinite(p.y))return null;local.points.add(new Ink.Pt(p.x-ox,p.y-oy,p.p,p.tilt,p.angle,p.azimuth));}Result match=recognizeLocal(local,unit);if(match==null)return null;ArrayList<Ink.Pt> points=new ArrayList<>();for(Ink.Pt p:match.stroke.points)points.add(pt(p.x+ox,p.y+oy));return new Result(match.kind,source,points,!match.kind.equals("line"));}
    static Result recognizeLocal(Ink.Stroke source,float unit){
        ArrayList<Ink.Pt> raw=denoise(resample(source.points,Math.min(256,Math.max(96,source.points.size()))));float path=length(raw);float[] box=bounds(raw);float w=box[2]-box[0],h=box[3]-box[1],diagonal=(float)Math.hypot(w,h);unit=Math.max(.01f,unit);if(diagonal<32*unit||path<32*unit)return null;ArrayList<Ink.Pt> samples=resample(raw,SAMPLES);Ink.Pt a=samples.get(0),z=samples.get(SAMPLES-1);float end=Ink.dist(a.x,a.y,z.x,z.y);
        if(end>diagonal*.8f&&path/end<1.12f){float max=0,error=0;for(Ink.Pt p:samples){float d=Ink.segment(p.x,p.y,a.x,a.y,z.x,z.y);max=Math.max(max,d);error+=d*d;}if(max/diagonal<.055f&&Math.sqrt(error/SAMPLES)/diagonal<.025f){float angle=snapAngle((float)Math.atan2(z.y-a.y,z.x-a.x));return new Result("line",source,Arrays.asList(pt(a.x,a.y),pt(a.x+end*(float)Math.cos(angle),a.y+end*(float)Math.sin(angle))),false);}}
        if(Math.min(w,h)<20*unit||end>diagonal*.24f||source.points.size()<5)return null;if(end>.0001f)raw.add(raw.get(0));path=length(raw);samples=resample(raw,SAMPLES+1);samples.remove(samples.size()-1);ArrayList<Ink.Pt> hull=hull(samples);float hullArea=Math.abs(area(hull)),signed=Math.abs(area(samples));if(hullArea<1||signed/hullArea>1.28f)return null;float deficit=1-signed/hullArea;
        PolygonFitter.Match polygon=PolygonFitter.fit(samples,diagonal,path);Result oval=ellipse(source,samples,path,unit);float ovalScore=oval==null?Float.MAX_VALUE:boundaryError(samples,oval.stroke.points)/diagonal;PolygonFitter.Match regular=deficit<.045f?PolygonFitter.regularFit(samples,diagonal):null;if(regular!=null&&(oval==null||regular.score<ovalScore*.88f)&&(polygon==null||polygon.kind.equals("polygon")&&regular.score<polygon.score+.006f))polygon=regular;ShapeTemplates.Match symbol=ShapeTemplates.fit(samples,diagonal,deficit,path);
        if(symbol!=null&&!(!symbol.kind.equals("star")&&polygon!=null&&polygon.score+.002f<symbol.score)&&(oval==null||symbol.score+.004f<ovalScore||deficit>.045f&&!symbol.kind.equals("cloud"))&&(polygon==null||polygon.kind.equals("polygon")||symbol.score<polygon.score))return new Result(symbol.kind,source,symbol.points,true);
        if(polygon!=null&&(oval==null||polygon.score<ovalScore*.85f+.001f))return new Result(polygon.kind,source,polygon.points,true);return oval;
    }
    static float cross(Ink.Pt a,Ink.Pt b,Ink.Pt c){return (b.x-a.x)*(c.y-a.y)-(b.y-a.y)*(c.x-a.x);}
    static boolean rightAngles(List<Ink.Pt> hull){for(int i=0;i<4;i++){Ink.Pt a=hull.get((i+3)%4),b=hull.get(i),c=hull.get((i+1)%4);float x=a.x-b.x,y=a.y-b.y,u=c.x-b.x,v=c.y-b.y;if(Math.abs(x*u+y*v)>.16f*Math.hypot(x,y)*Math.hypot(u,v))return false;}return true;}
    static ArrayList<Ink.Pt> hull(List<Ink.Pt> input){ArrayList<Ink.Pt> sorted=new ArrayList<>(input);sorted.sort((a,b)->a.x==b.x?Float.compare(a.y,b.y):Float.compare(a.x,b.x));ArrayList<Ink.Pt> h=new ArrayList<>();for(Ink.Pt p:sorted){while(h.size()>1&&cross(h.get(h.size()-2),h.get(h.size()-1),p)<=0)h.remove(h.size()-1);h.add(p);}int lower=h.size();for(int i=sorted.size()-2;i>=0;i--){Ink.Pt p=sorted.get(i);while(h.size()>lower&&cross(h.get(h.size()-2),h.get(h.size()-1),p)<=0)h.remove(h.size()-1);h.add(p);}if(h.size()>1)h.remove(h.size()-1);return h;}
    static void simplify(ArrayList<Ink.Pt> hull,float tolerance){while(hull.size()>3){int index=-1;float least=tolerance;for(int i=0;i<hull.size();i++){Ink.Pt p=hull.get(i),a=hull.get((i+hull.size()-1)%hull.size()),b=hull.get((i+1)%hull.size());float d=Ink.segment(p.x,p.y,a.x,a.y,b.x,b.y);if(d<least){least=d;index=i;}}if(index<0)break;hull.remove(index);}}
    static float perimeter(List<Ink.Pt> p){float result=0;for(int i=0;i<p.size();i++){Ink.Pt a=p.get(i),b=p.get((i+1)%p.size());result+=Ink.dist(a.x,a.y,b.x,b.y);}return result;}
    static float boundaryError(List<Ink.Pt> samples,List<Ink.Pt> polygon){float sum=0;for(Ink.Pt p:samples){float best=Float.MAX_VALUE;for(int j=0;j<polygon.size();j++){Ink.Pt a=polygon.get(j),b=polygon.get((j+1)%polygon.size());best=Math.min(best,Ink.segment(p.x,p.y,a.x,a.y,b.x,b.y));}sum+=best*best;}return (float)Math.sqrt(sum/samples.size());}
    static ArrayList<Ink.Pt> rectangle(List<Ink.Pt> hull,List<Ink.Pt> samples){float best=Float.MAX_VALUE;ArrayList<Ink.Pt> result=null;for(int edge=0;edge<4;edge++){Ink.Pt a=hull.get(edge),b=hull.get((edge+1)%4);float angle=snapAngle((float)Math.atan2(b.y-a.y,b.x-a.x)),c=(float)Math.cos(angle),s=(float)Math.sin(angle),l=Float.MAX_VALUE,t=l,r=-l,d=-l;for(Ink.Pt p:hull){float x=p.x*c+p.y*s,y=-p.x*s+p.y*c;l=Math.min(l,x);r=Math.max(r,x);t=Math.min(t,y);d=Math.max(d,y);}float w=r-l,h=d-t;if(Math.min(w,h)<1)continue;if(Math.abs(w-h)/Math.max(w,h)<.12f){float side=(w+h)/2,cx=(l+r)/2,cy=(t+d)/2;l=cx-side/2;r=cx+side/2;t=cy-side/2;d=cy+side/2;}ArrayList<Ink.Pt> candidate=new ArrayList<>();for(float[] p:new float[][]{{l,t},{r,t},{r,d},{l,d}})candidate.add(pt(p[0]*c-p[1]*s,p[0]*s+p[1]*c));float error=boundaryError(samples,candidate);if(error<best){best=error;result=candidate;}}return result;}
    static Result ellipse(Ink.Stroke source,List<Ink.Pt> samples,float path,float unit){float mx=0,my=0;for(Ink.Pt p:samples){mx+=p.x;my+=p.y;}mx/=samples.size();my/=samples.size();double xx=0,yy=0,xy=0;for(Ink.Pt p:samples){xx+=(p.x-mx)*(p.x-mx);yy+=(p.y-my)*(p.y-my);xy+=(p.x-mx)*(p.y-my);}float angle=(float)(.5*Math.atan2(2*xy,xx-yy)),c=(float)Math.cos(angle),s=(float)Math.sin(angle),l=Float.MAX_VALUE,t=l,r=-l,b=-l;for(Ink.Pt p:samples){float x=p.x*c+p.y*s,y=-p.x*s+p.y*c;l=Math.min(l,x);r=Math.max(r,x);t=Math.min(t,y);b=Math.max(b,y);}float rx=(r-l)/2,ry=(b-t)/2,cx=(l+r)/2,cy=(t+b)/2;if(Math.min(rx,ry)<10*unit)return null;float radialMean=0;for(Ink.Pt p:samples)radialMean+=Math.hypot((p.x*c+p.y*s-cx)/rx,(-p.x*s+p.y*c-cy)/ry);radialMean/=samples.size();rx*=radialMean;ry*=radialMean;float mean=0,max=0;for(Ink.Pt p:samples){float x=(p.x*c+p.y*s-cx)/rx,y=(-p.x*s+p.y*c-cy)/ry,error=Math.abs((float)Math.hypot(x,y)-1);mean+=error*error;max=Math.max(max,error);}if(Math.sqrt(mean/samples.size())>.095||max>.24)return null;float circumference=(float)(Math.PI*(3*(rx+ry)-Math.sqrt((3*rx+ry)*(rx+3*ry))));if(path/circumference<.78f||path/circumference>1.22f)return null;boolean circle=Math.abs(rx-ry)/Math.max(rx,ry)<.12f;if(circle)rx=ry=(rx+ry)/2;ArrayList<Ink.Pt> points=new ArrayList<>();for(int i=0;i<=128;i++){float a=(float)(i*Math.PI*2/128),x=cx+rx*(float)Math.cos(a),y=cy+ry*(float)Math.sin(a);points.add(pt(x*c-y*s,x*s+y*c));}return new Result(circle?"circle":"ellipse",source,points,true);}
    /** Existing shape tools also get gentle axis and square/circle assistance on release. */
    public static Ink.Stroke alignTool(Ink.Stroke input){if(input.points.size()<2||!(input.tool.equals("line")||input.tool.equals("arrow")||input.tool.equals("rect")||input.tool.equals("ellipse")))return input;Ink.Pt a=input.points.get(0),b=input.points.get(1);Ink.Stroke result=input.copy();if(input.tool.equals("line")||input.tool.equals("arrow")){float distance=Ink.dist(a.x,a.y,b.x,b.y),angle=snapAngle((float)Math.atan2(b.y-a.y,b.x-a.x));Ink.Pt end=pt(a.x+distance*(float)Math.cos(angle),a.y+distance*(float)Math.sin(angle));result.points.clear();result.points.add(a);result.points.add(end);if(input.tool.equals("arrow")){float len=Math.max(18,input.width*4);result.points.add(pt(end.x-len*(float)Math.cos(angle-.5f),end.y-len*(float)Math.sin(angle-.5f)));result.points.add(end);result.points.add(pt(end.x-len*(float)Math.cos(angle+.5f),end.y-len*(float)Math.sin(angle+.5f)));}return result;}if(input.tool.equals("rect")||input.tool.equals("ellipse")){float w=Math.abs(b.x-a.x),h=Math.abs(b.y-a.y);if(Math.max(w,h)>0&&Math.abs(w-h)/Math.max(w,h)<.12f){float side=(w+h)/2;result.points.set(1,pt(a.x+Math.copySign(side,b.x-a.x),a.y+Math.copySign(side,b.y-a.y)));return result;}}return input;}
}
